  }

  if (s.refundError) {
    const names = s.order?.items.map((i) => i.name).join(", ") ?? "";
    return `${hi} I couldn't match that to an item on ${s.order?.order_id}. That order contains: ${names}. Which of those would you like refunded?`;
  }

  if (s.tracking) {
    const t = s.tracking;
    return `${hi} order ${t.order_id} is ${STATUS_TEXT[t.status] ?? t.status}. It's with ${t.carrier}, tracking number ${t.tracking_number}, so you can follow it directly with them. Anything else I can check?`;
